    if col in 'ABCDEFGHIJK' and row!=1 and c.find('m:v',ns) is None and c.find('m:is',ns) is None:
        if c.get('s') not in ('38',): # all empty style except maybe? include all
            rows.add(row)
print(sorted(rows), len(rows))
# count empty cells in these rows A-K
count=0
for c in cells:
    r=c.get('r'); col=''.join(ch for ch in r if ch.isalpha()); row=int(''.join(ch for ch in r if ch.isdigit()))
    if col in 'ABCDEFGHIJK' and row in rows:
        if c.find('m:v',ns) is None and c.find('m:is',ns) is None:
            count+=1
print('empty count', count)
# list rows and cols count
from collections import defaultdict
by=defaultdict(list)
for c in cells:
    r=c.get('r'); col=''.join(ch for ch in r if ch.isalpha()); row=int(''.join(ch for ch in r if ch.isdigit()))
    if row in rows and col in 'ABCDEFGHIJK' and c.find('m:v',ns) is None and c.find('m:is',ns) is None:
        by[row].append(col)
for row in sorted(by):
    print(row, len(by[row]), ''.join(by[row]))
